bad_code:
// 1. 미초기화 지역 변수 사용 (쓰레기 값 읽기)
int uninit_local;
volatile int val1 = uninit_local + 1;

// 2. 와일드 포인터(미초기화 포인터) 역참조
int* wild_ptr;
volatile int val2 = *wild_ptr;

good_code:
int value = 0;
int* wild_ptr = &value;
volatile int val2 = *wild_ptr;

bad_code:
// 3. 스택 버퍼 오버플로우
char ssTemp[10];
sprintf(ssTemp, "dfsljsdlkfjsldkfdlfksldkfsjlfd");

// 4. 스택 버퍼 오버플로우
char ssTemp[10];
memcpy(ssTemp, "dlfkjsdklfjdslfksdjl", 11);

// 5. 스택 버퍼 오버플로우
char ssTemp[10];
sprintf(ssTemp, "123456789");
strcat(ssTemp, "1234");

good_code:
char ssTemp[10];
snprintf(ssTemp, sizeof(ssTemp), "123456789");
strncat(ssTemp, "1234", sizeof(ssTemp) - strlen(ssTemp) - 1);

bad_code:
// 6. 동적 할당 후 부분 초기화된 배열의 미정의 요소 읽기
int* dyn_arr = new int[10];
dyn_arr[0] = 1;
volatile int val5 = dyn_arr[5];
delete[] dyn_arr;

good_code:
int* dyn_arr = new int[10]();
dyn_arr[0] = 1;
volatile int val5 = dyn_arr[5];
delete[] dyn_arr;

bad_code:
// 7. 조건부 초기화 누락 변수 사용
int cond_var;
bool flag = false;
if (flag) {
    cond_var = 100;
}
volatile int val7 = cond_var;

good_code:
int cond_var = 0;
bool flag = false;
if (flag) {
    cond_var = 100;
}
volatile int val7 = cond_var;

bad_code:
